/* The five under test. */
void eita_sstore_gas_legacy(uint64_t *, uint64_t, const u256_t *, const u256_t *, const u256_t *, uint64_t);
void eita_sstore_gas_eip1283(uint64_t *, uint64_t, const u256_t *, const u256_t *, const u256_t *, uint64_t);
void eita_sstore_gas_eip2200(uint64_t *, uint64_t, const u256_t *, const u256_t *, const u256_t *, uint64_t);
void eita_sstore_gas_berlin(uint64_t *, uint64_t, const u256_t *, const u256_t *, const u256_t *, uint64_t);
void eita_sstore_gas_london(uint64_t *, uint64_t, const u256_t *, const u256_t *, const u256_t *, uint64_t);

/* A u256 that satisfies a bit pattern: the three values are chosen so that
   every zero/equality predicate the pattern asks for holds, and the pattern
   is skipped when it asks for something contradictory (orig==cur and
   orig zero but cur not, and so on) — those cannot arise from a real
   SSTORE and the plans are not defined to agree on them. */
static int build(unsigned b, u256_t *o, u256_t *c, u256_t *n) {
    const int oz = b & 1, cz = (b >> 1) & 1, nz = (b >> 2) & 1;
    const int oec = (b >> 3) & 1, cen = (b >> 4) & 1, oen = (b >> 5) & 1;
    memset(o, 0, sizeof *o); memset(c, 0, sizeof *c); memset(n, 0, sizeof *n);
    o->limb[0] = oz ? 0 : 1; c->limb[0] = cz ? 0 : 2; n->limb[0] = nz ? 0 : 3;
    if (oec) c->limb[0] = o->limb[0];
    if (cen) n->limb[0] = c->limb[0];
    if (oen) n->limb[0] = o->limb[0];
    /* re-derive and require the pattern to be self-consistent */
    const int Oz = o->limb[0] == 0, Cz = c->limb[0] == 0, Nz = n->limb[0] == 0;
    const int Oec = o->limb[0] == c->limb[0], Cen = c->limb[0] == n->limb[0];
    const int Oen = o->limb[0] == n->limb[0];
    return Oz == oz && Cz == cz && Nz == nz && Oec == oec && Cen == cen && Oen == oen;
}

int main(void) {
    unsigned checked = 0, skipped = 0, bad = 0;
    for (unsigned i = 0; i < sizeof VECTORS / sizeof VECTORS[0]; i++) {
        const SV *v = &VECTORS[i];
        u256_t o, c, n;
        if (!build(v->bits, &o, &c, &n)) { skipped++; continue; }
        uint64_t out[2] = { 0, 0 };
        const uint64_t cold = (v->bits >> 6) & 1;
        if (!strcmp(v->sched, "legacy")) eita_sstore_gas_legacy(out, v->refund, &o, &c, &n, cold);
        if (!strcmp(v->sched, "eip1283")) eita_sstore_gas_eip1283(out, v->refund, &o, &c, &n, cold);
        if (!strcmp(v->sched, "eip2200")) eita_sstore_gas_eip2200(out, v->refund, &o, &c, &n, cold);
        if (!strcmp(v->sched, "berlin")) eita_sstore_gas_berlin(out, v->refund, &o, &c, &n, cold);
        if (!strcmp(v->sched, "london")) eita_sstore_gas_london(out, v->refund, &o, &c, &n, cold);
        checked++;
        if (out[0] != v->cost || out[1] != v->out_refund) {
            printf("FAIL %s bits=%u refund=%llu: got (%llu, %llu) want (%llu, %llu)\n",
                   v->sched, v->bits, (unsigned long long)v->refund,
                   (unsigned long long)out[0], (unsigned long long)out[1],
                   (unsigned long long)v->cost, (unsigned long long)v->out_refund);
            if (++bad > 20) { printf("…\n"); break; }
        }
    }
    printf("sstore gas vectors: %u checked, %u unreachable patterns skipped, %u failed\n",
           checked, skipped, bad);
    /* A build that skipped every pattern would also report zero failures, so
       the reachable count is pinned. 15 of the 64 predicate combinations are
       self-consistent (only one of {orig,cur,new} may be zero, and the three
       equalities are a partition), times 2 for `cold`, times the refund
       probes, times the schedules. The other patterns cannot arise from an
       SSTORE — and are covered by `applyRow_is_*` regardless, which quantify
       over all 128. */
    const unsigned expect = 1350;
    if (checked != expect) {
        printf("FAIL: %u patterns reachable, expected %u — the generator or the\n"
               "      consistency filter changed, and a silent skip reads as a pass\n",
               checked, expect);
        return 1;
    }
    return bad != 0;
}
